from itertools import combinations, product
from problems import DominatingSet, Sat, InvalidInstance

def dominating_set_bruteforce(instance):
    DominatingSet.validate(instance)
    n = instance['n']
    edges = instance['edges']
    k = instance['k']
    if k < 0:
        return False
    if n == 0:
        return True
    # adjacency set
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    # check subsets up to size k
    for size in range(0, min(k, n) + 1):
        for comb in combinations(range(n), size):
            D = set(comb)
            ok = True
            for v in range(n):
                if v not in D and not (adj[v] & D):
                    ok = False
                    break
            if ok:
                return True
    return False

def sat_bruteforce(instance):
    Sat.validate(instance)
    m = instance['num_vars']
    clauses = instance['clauses']
    # early unsat if any empty clause
    for cl in clauses:
        if not cl:
            return False
    for assignment in product([False, True], repeat=m):
        good = True
        for clause in clauses:
            clause_sat = False
            for lit in clause:
                var = abs(lit) - 1
                val = assignment[var]
                if lit > 0 and val:
                    clause_sat = True
                    break
                if lit < 0 and not val:
                    clause_sat = True
                    break
            if not clause_sat:
                good = False
                break
        if good:
            return True
    return False

if __name__ == '__main__':
    import json, sys
    data = json.load(sys.stdin)
    if data.get('type') == 'dom':
        print(dominating_set_bruteforce(data['instance']))
    else:
        print(sat_bruteforce(data['instance']))
EOF"}

